//! Trigger events with new subjects (cards4-triggers-durations): "Whenever a player casts
//! an instant or sorcery card" (Eye of the Storm: a spell cast from a card, not a copy).

use crate::combat2_common::supported;
use crate::td_next_turn_durations::mana;
use mtg_engine::testing::*;
use mtg_engine::turn::Step;
use mtg_engine::*;

#[test]
fn eye_of_the_storm_exiles_cast_cards_and_the_caster_casts_copies_of_all_of_them() {
    cr!("601.2a", "707.12", "607.2a");
    ruling!(
        "Eye of the Storm",
        "A copy of a card (such as those generated by Eye of the Storm itself) won’t trigger this ability"
    );
    ruling!(
        "Eye of the Storm",
        "the player copies all cards exiled with Eye of the Storm, not just the cards they own"
    );
    supported("Eye of the Storm");
    let mut t = TestGame::new(2);
    t.battlefield(P0, "Eye of the Storm");
    t.advance_to(P1, Step::PrecombatMain);
    let bolt = t.hand(P1, "Lightning Bolt");
    mana(&mut t, P1);
    t.cast_with(P1, bolt, &[Entity::Player(P0)]).unwrap();
    // P1 casts the copy of the Bolt, at P0.
    t.answer_yes(P1, true);
    t.answer_targets(P1, &[Entity::Player(P0)]);
    t.resolve_all();
    assert!(t.in_exile("Lightning Bolt"));
    assert_eq!(t.life(P0), 17, "only the copy resolved");
    // P0's Shock: P0 copies both exiled cards and casts the copies at P1.
    t.advance_to(P0, Step::PrecombatMain);
    let shock = t.hand(P0, "Shock");
    mana(&mut t, P0);
    t.cast_with(P0, shock, &[Entity::Player(P1)]).unwrap();
    t.answer_yes(P0, true);
    t.answer_targets(P0, &[Entity::Player(P1)]);
    t.answer_targets(P0, &[Entity::Player(P1)]);
    t.resolve_all();
    assert_eq!(t.life(P1), 15);
    assert!(t.in_exile("Shock"));
}

fn soldier_tokens(t: &TestGame) -> Vec<ObjectId> {
    t.g.battlefield
        .iter()
        .copied()
        .filter(|o| t.g.obj(*o).chars.has_subtype("Soldier"))
        .collect()
}

#[test]
fn kaya_copies_a_creature_card_exiled_from_the_battlefield_or_graveyard() {
    cr!("603.2c", "707.2", "611.2a");
    ruling!(
        "Kaya, Spirits' Justice",
        "The target token copies the printed values of the card in exile"
    );
    supported("Kaya, Spirits' Justice");
    let mut t = TestGame::new(2);
    t.battlefield(P0, "Kaya, Spirits' Justice");
    t.advance_to(P0, Step::PrecombatMain);
    let alarm = t.hand(P0, "Raise the Alarm");
    mana(&mut t, P0);
    t.cast_with(P0, alarm, &[]).unwrap();
    t.resolve_all();
    let tokens = soldier_tokens(&t);
    assert_eq!(tokens.len(), 2);
    // A creature card exiled from P0's graveyard.
    let wurm = t.graveyard(P0, "Craw Wurm");
    t.answer_targets(P0, &[Entity::Object(tokens[0])]);
    t.answer_yes(P0, true);
    let exiled = t.g.exile_object(wurm, None).unwrap();
    t.answer_choose(P0, &[Entity::Object(exiled)]);
    t.resolve_all();
    let tok = t.obj_now(tokens[0]);
    assert_eq!(tok.chars.name.as_str(), "Craw Wurm");
    assert!(tok.chars.has_keyword(mtg_engine::keywords::KeywordKind::Flying));
    assert_eq!(t.pt(tokens[0]), (6, 4));
    // A creature P0 controls exiled from the battlefield.
    let bears = t.battlefield(P0, "Grizzly Bears");
    t.answer_targets(P0, &[Entity::Object(tokens[1])]);
    t.answer_yes(P0, true);
    let exiled = t.g.exile_object(bears, None).unwrap();
    t.answer_choose(P0, &[Entity::Object(exiled)]);
    t.resolve_all();
    assert_eq!(t.obj_now(tokens[1]).chars.name.as_str(), "Grizzly Bears");
    // Until end of turn.
    t.advance_to(P1, Step::Upkeep);
    assert!(t.obj_now(tokens[0]).chars.has_subtype("Soldier"));
    assert!(t.obj_now(tokens[1]).chars.has_subtype("Soldier"));
}

#[test]
fn kaya_ignores_cards_exiled_from_an_opponents_graveyard() {
    cr!("603.2c");
    let mut t = TestGame::new(2);
    t.battlefield(P0, "Kaya, Spirits' Justice");
    let wurm = t.graveyard(P1, "Craw Wurm");
    t.g.exile_object(wurm, None);
    t.g.settle();
    assert_eq!(t.stack_len(), 0);
}

/// Search the City enters with `top` (top first) as P0's whole library.
fn search_the_city(top: &[&str]) -> TestGame {
    let mut t = TestGame::new(2);
    t.g.players[0].library.clear();
    for n in top.iter().rev() {
        t.library_top(P0, n);
    }
    t.advance_to(P0, Step::PrecombatMain);
    t.enter(P0, "Search the City");
    t.resolve_all();
    t
}

#[test]
fn search_the_city_returns_an_exiled_card_named_like_the_card_played() {
    cr!("607.2a", "603.2");
    ruling!(
        "Search the City",
        "You can put only one card into its owner’s hand for each card you play."
    );
    ruling!(
        "Search the City",
        "To “play a card” is to play that card as a land or cast that card as a spell"
    );
    supported("Search the City");
    let mut t = search_the_city(&[
        "Lightning Bolt",
        "Lightning Bolt",
        "Forest",
        "Grizzly Bears",
        "Shock",
    ]);
    assert_eq!(t.g.exile.len(), 5);
    // Casting a Bolt: one of the exiled Bolts goes to P0's hand.
    let bolt = t.hand(P0, "Lightning Bolt");
    mana(&mut t, P0);
    let hand = t.hand_size(P0);
    t.cast_with(P0, bolt, &[Entity::Player(P1)]).unwrap();
    t.answer_yes(P0, true);
    t.resolve_all();
    assert_eq!(t.hand_size(P0), hand, "the Bolt cast, an exiled Bolt returned");
    assert_eq!(t.g.exile.len(), 4);
    // A card no exiled card shares a name with doesn't trigger it.
    let giant = t.hand(P0, "Hill Giant");
    mana(&mut t, P0);
    t.cast_with(P0, giant, &[]).unwrap();
    t.g.settle();
    assert_eq!(t.stack_len(), 1);
    t.resolve_all();
    // Playing a land with an exiled card's name.
    let forest = t.hand(P0, "Forest");
    t.answer_yes(P0, true);
    t.play_land(P0, forest).unwrap();
    t.resolve_all();
    assert_eq!(t.g.exile.len(), 3);
    assert!(t.g.extra_turns.is_empty());
}

#[test]
fn search_the_city_is_sacrificed_for_an_extra_turn_once_empty() {
    cr!("607.2a", "500.7");
    let mut t = search_the_city(&["Shock"]);
    assert_eq!(t.g.exile.len(), 1);
    let shock = t.hand(P0, "Shock");
    mana(&mut t, P0);
    t.cast_with(P0, shock, &[Entity::Player(P1)]).unwrap();
    t.answer_yes(P0, true);
    t.resolve_all();
    assert!(t.in_graveyard(P0, "Search the City"));
    assert_eq!(t.g.extra_turns, vec![P0]);
}
